#include "controller.hpp"
namespace academy {Controller::Controller(Device&b):board_(b){}void Controller::tick(){const std::string&x=board_.input.text;board_.output.error=false;if(board_.input.fault){selected_=false;frame_.clear();board_.output.error=true;board_.output.state="spi error";return;}if(x=="CS:LOW"){selected_=true;frame_.clear();board_.output.state="selected";}else if(x=="CS:HIGH"){if(!selected_){board_.output.error=true;}else{board_.output.display=frame_;board_.output.state="spi ready";}selected_=false;}else if(x.rfind("WRITE:",0)==0){if(!selected_)board_.output.error=true;else frame_+=x.substr(6);}else if(!x.empty())board_.output.error=true;}}
